  LinearLayout dates=new LinearLayout(this);dates.setBaselineAligned(false);for(int n=0;n<7;n++){LocalDate date=first.plusDays(n);boolean sel=date.equals(selected);LinearLayout cell=Ui.column(this);cell.setGravity(Gravity.CENTER);Ui.pad(cell,0,8,0,8);TextView day=Ui.centered(this,days[n].substring(1),12,sel?Color.WHITE:Ui.MUTED);TextView number=Ui.centered(this,String.valueOf(date.getDayOfMonth()),16,sel?Color.WHITE:Ui.INK);cell.addView(day,new LinearLayout.LayoutParams(-1,dp(18)));Ui.gap(cell,6);cell.addView(number,new LinearLayout.LayoutParams(-1,dp(22)));if(sel)cell.setBackground(Ui.round(Ui.TEAL,14,this));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(64),1);lp.leftMargin=dp(2);lp.rightMargin=dp(2);dates.addView(cell,lp);cell.setOnClickListener(v->{selected=date;schedule();});}p.addView(dates,new LinearLayout.LayoutParams(-1,dp(64)));Ui.gap(p,24);
  List<ScheduleEngine.Occurrence> entries=store.onDate(selected);if(entries.isEmpty())p.addView(text(store.calendar().includes(selected)?"这一天没有课程":"这一天不在上课日期内",17,Ui.MUTED));
