  Ui.gap(p,10);action(p,"管理所有课程",store.courses.size()+" 条安排，可编辑停课的课程",this::allCourses);action(p,"分享课表文字","复制后可导入另一部手机",()->{try{copy("课表",store.exportCourses().toString(2));}catch(Exception e){toast(e.getMessage());}});
